    {"path":"reports/spec-review/cloud-orchestration/attempt-1/round-1/integrated-summary.json","sha256":"24e1688c07ea04a4d983ee13aaf534b8ce3c7adaade19c80e89cfc9fc468dc41"}
  ],
  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "AMBIGUITY",
      "result": "PASS",
      "severity": "Major",
      "finding": "REQ-002–010, Roles and Permissions, and Main Workflows define supported owners, authorization stages, immutable bindings, reconciliation and verification outcomes sufficiently for design."
    },
    {
      "id": "CONTRADICTION",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Recognizing existing owners does not imply executing unsupported owners; development approval explicitly excludes cloud writes. Historical #423 evidence is distinguished from this feature's future implementation."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "Requirements Main Workflows requires dependency graphs where a failed predecessor blocks dependents and preserves successful-unit receipts; Edge Cases also requires an explicit no-op result without fake apply. AC-006 covers concurrency/replay/timeouts and AC-009 covers unhealthy or missing observations, but no acceptance scenario exercises either dependency-graph partial failure or no-op execution. A verifier could accept a suite that submits dependent writes after predecessor failure or fabricates an apply for an empty preview. These are missing observable product acceptance cases, not missing implementation detail; their safety and audit consequences justify Major."
    },
    {
      "id": "ASSUMPTIONS-RESOLVABLE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Assumptions and Open Questions identify GitHub Actions, initial owners, and required target, federation, health, backup and budget inputs; missing deployment prerequisites block live operation rather than invite substitution."
    },
    {
      "id": "APPROVAL-BOUNDARY",
      "result": "PASS",
      "severity": "Critical",
      "finding": "REQ-004–006 and AC-004–006 require authenticated, distinct prepare/apply authorization at the write boundary, immutable binding, revocation/expiry rejection and replay protection. Cleanup requires separate authorization."
    },
    {
      "id": "DOWNSTREAM-READINESS",
      "result": "PASS",
      "severity": "Major",
      "finding": "Supported execution paths, non-goals, cloud lifecycle, evidence classifications and deployment prerequisites are specified without requiring downstream reviewers to invent product behavior. The missing negative acceptance scenarios are reported separately under EDGE-CASE-COVERAGE."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Major",
      "finding": "The host states that no domain/ directory exists; investigation.md independently records domain-sync skipped for that reason."
    }
  ]
}
